+class ContactForm {
+  constructor() {
+    this.form = document.getElementById('contactForm');
+    this.fullNameInput = document.getElementById('fullName');
+    this.emailInput = document.getElementById('email');
+    this.phoneInput = document.getElementById('phone');
+    this.successMessage = document.getElementById('successMessage');
+
+    this.touched = {
+      fullName: false,
+      email: false,
+      phone: false
+    };
+
+    this.init();
+  }
+
+  init() {
+    this.form.addEventListener('submit', (e) => this.handleSubmit(e));
+    this.fullNameInput.addEventListener('blur', () => this.handleFieldBlur('fullName'));
+    this.emailInput.addEventListener('blur', () => this.handleFieldBlur('email'));
+    this.phoneInput.addEventListener('blur', () => this.handleFieldBlur('phone'));
+  }
+
+  handleFieldBlur(fieldName) {
+    this.touched[fieldName] = true;
+    this.validateField(fieldName);
+  }
+
+  validateField(fieldName) {
+    let error = '';
+
+    if (fieldName === 'fullName') {
+      const value = this.fullNameInput.value.trim();
+      if (!value) {
+        error = 'Full name is required.';
+      } else if (value.length < 2) {
+        error = 'Full name must be at least 2 characters.';
+      }
+    } else if (fieldName === 'email') {
+      const value = this.emailInput.value.trim();
+      if (!value) {
+        error = 'Email address is required.';
+      } else if (!this.isValidEmail(value)) {
+        error = 'Please enter a valid email address.';
+      }
+    } else if (fieldName === 'phone') {
+      const value = this.phoneInput.value.trim();
+      if (value && !this.isValidPhone(value)) {
+        error = 'Please enter a valid phone number.';
+      }
+    }
+
+    this.setFieldError(fieldName, error);
+  }
+
+  isValidEmail(email) {
+    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
+  }
+
+  isValidPhone(phone) {
+    return /^[\d\s\-().+]{7,}$/.test(phone.replace(/\s/g, ''));
+  }
+
+  setFieldError(fieldName, error) {
+    const input = this[fieldName + 'Input'];
+    const errorElement = document.getElementById(fieldName + 'Error');
+
+    if (error && this.touched[fieldName]) {
+      input.setAttribute('aria-invalid', 'true');
+      errorElement.textContent = error;
+    } else {
+      input.setAttribute('aria-invalid', 'false');
+      errorElement.textContent = '';
+    }
+  }
+
+  handleSubmit(e) {
+    e.preventDefault();
+
+    this.touched.fullName = true;
+    this.touched.email = true;
+    this.touched.phone = true;
+
+    this.validateField('fullName');
+    this.validateField('email');
+    this.validateField('phone');
+
+    if (this.isFormValid()) {
+      this.submitForm();
+    } else {
+      this.fullNameInput.focus();
+    }
+  }
+
+  isFormValid() {
+    const fullNameError = document.getElementById('fullNameError').textContent;
+    const emailError = document.getElementById('emailError').textContent;
+    const phoneError = document.getElementById('phoneError')?.textContent || '';
+
+    return !fullNameError && !emailError && !phoneError;
+  }
+
+  submitForm() {
+    const formData = {
+      fullName: this.fullNameInput.value.trim(),
+      email: this.emailInput.value.trim(),
+      phone: this.phoneInput.value.trim()
+    };
+
+    console.log('Form submitted:', formData);
+
+    this.form.style.display = 'none';
+    this.successMessage.setAttribute('aria-hidden', 'false');
+    this.successMessage.focus();
+
+    setTimeout(() => {
+      this.form.reset();
+      this.form.style.display = 'flex';
+      this.successMessage.setAttribute('aria-hidden', 'true');
+      this.touched = { fullName: false, email: false, phone: false };
+      this.fullNameInput.focus();
+    }, 3000);
+  }
+}
+
+document.addEventListener('DOMContentLoaded', () => {
+  new ContactForm();
